export const queryKeys = {
  user: () => ["user"],
  info: () => ["info"],
  bots: {
    all: () => ["bots"],
    detail: (id) => ["bots", id],
    apps: (id) => ["bots", id, "apps"],
    traces: (id, limit) => ["bots", id, "traces", { limit }],
    trace: (botId, traceId) => ["bots", botId, "traces", traceId],
    channels: (id) => ["bots", id, "channels"],
    contacts: (id) => ["bots", id, "contacts"],
    messages: (id, limit = 30, cursor) => ["bots", id, "messages", { limit, cursor }],
    stats: () => ["bots", "stats"],
    webhookLogs: (botId, channelId, limit = 50) => [
      "bots",
      botId,
      "webhook-logs",
      { channelId, limit },
    ],
  },
  apps: {
    all: (opts) => ["apps", opts],
    detail: (id) => ["apps", id],
    installations: (appId) => ["apps", appId, "installations"],
    installation: (appId, iid) => ["apps", appId, "installations", iid],
    reviews: (appId) => ["apps", appId, "reviews"],
    eventLogs: (appId, iid, limit = 50) => [
      "apps",
      appId,
      "installations",
      iid,
      "event-logs",
      { limit },
    ],
    apiLogs: (appId, iid, limit = 50) => [
      "apps",
      appId,
      "installations",
      iid,
      "api-logs",
      { limit },
    ],
  },
  marketplace: {
    apps: () => ["marketplace"],
    builtin: () => ["marketplace", "builtin"],
  },
  admin: {
    stats: () => ["admin", "stats"],
    users: () => ["admin", "users"],
    apps: () => ["admin", "apps"],
    aiConfig: () => ["admin", "ai-config"],
    oauthConfig: () => ["admin", "oauth-config"],
    oidcConfig: () => ["admin", "oidc-config"],
    registryConfig: () => ["admin", "registry-config"],
    registries: () => ["admin", "registries"],
    registrationConfig: () => ["admin", "registration-config"],
  },
  config: {
    availableModels: () => ["config", "available-models"],
  },
  passkeys: () => ["passkeys"],
  oauthAccounts: () => ["oauth-accounts"],
  oauthProviders: () => ["oauth-providers"],
};
